    for a, b, rule in refused:
        lines.append(f"kept apart {ids.fmt(a)} {ids.fmt(b)} ({RULES[rule]})")
    lines.append(f"{len(results)} groups, {len(surv_of)} members merged, {len(refused)} pairs kept apart")
    return lines, entries, {"surv_of": surv_of, "new": new_recs}


def cmd_merge(ctx, a):
    lines, entries, info = plan(ctx)
    surv_of = info["surv_of"]
    if a.apply and entries:
        register = {n: r for n, r in ctx.members.items() if n not in surv_of}
        register.update(info["new"])
        amap = {k: surv_of.get(v, v) for k, v in ctx.aliases.items()}
        amap.update(surv_of)
        rows = []
        for r in ctx.payments:
            n = ids.number(r["member"])
            if n is not None:
                m = aliases_mod.resolve(ctx.aliases, n)
                if m in surv_of:
                    r = {**r, "member": ids.fmt(surv_of[m])}
