                                "member": ids.fmt(e["surv"]), "merged": e["merged"], "rules": e["rules"],
                                "changes": e["changes"], "from": e["from"]})
        ctx.commit(register=register, alias_map=amap, payment_rows=rows, new_entries=new_entries)
    if not a.apply:
        lines.append("dry run: nothing written")
    return lines
